function prng(seed){var a=(seed>>>0)||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
function demoRun(seed){var R=prng(seed*32452867+19);var goals=['latency<100ms','cost<$500/mo','99.9% uptime'];var pool=['ingest-api','stream-queue','worker-pool','vector-index','cache-tier','audit-log','autoscaler'];var bp=[];pool.forEach(function(p){if(R()<0.6)bp.push(p);});if(bp.indexOf('audit-log')<0)bp.push('audit-log');var checks=[['latency',bp.indexOf('cache-tier')>=0||bp.indexOf('worker-pool')>=0],['cost',bp.length<=5],['uptime',bp.indexOf('autoscaler')>=0],['audit',bp.indexOf('audit-log')>=0]];var met=checks.filter(function(c){return c[1];}).length;return{goals:goals,blueprint:bp,constraints_met:met,constraints_total:checks.length,ready:met===checks.length};}
var SEED = 82501;
console.log(JSON.stringify(demoRun(SEED), null, 1));

